using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with a known type resolver (only WeatherForecast is included).
var options = new JsonSerializerOptions
{
    TypeInfoResolver = AppJsonContext.Default
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<T> directly.
JsonTypeInfo<WeatherForecast> typedInfo = options.GetTypeInfo<WeatherForecast>();
Console.WriteLine($"Got typed metadata  : {typedInfo.Type.Name}  (kind: {typedInfo.Kind})");

// Round-trip to prove it works:
var forecast = new WeatherForecast("Seattle", 18);
string json = JsonSerializer.Serialize(forecast, typedInfo);
Console.WriteLine($"Serialized          : {json}");

WeatherForecast? rt = JsonSerializer.Deserialize(json, typedInfo);
Console.WriteLine($"Deserialized        : {rt}");

// 2) Probe without throwing — TryGetTypeInfo returns false when the type
//    isn't known to the resolver instead of throwing NotSupportedException.
bool found = options.TryGetTypeInfo(typeof(UnknownType), out JsonTypeInfo? probed);
Console.WriteLine();
Console.WriteLine($"TryGetTypeInfo for UnknownType => found: {found}, info: {probed?.Type.Name ?? "(null)"}");

if (!found)
    Console.WriteLine("Metadata not available — no exception thrown.");

